import React, { useEffect, useState, useCallback, useRef } from 'react';
import { useParams, useNavigate, useLocation } from 'react-router-dom';
import { getScheduleById, getSeatsByVenue, getLocksBySchedule, lockSeat, unlockSeat } from '../../services/api';
import { useAuth } from '../../context/AuthContext';
import SeatLayout from '../../components/SeatLayout';

// Seats entity: seatId, seatNumber, seatType, price, venueId
// SeatLock entity: lockId, seatId, userId, scheduleId, status

const LOCK_TIMEOUT_MINUTES = 5; // matches backend expiry

export default function SeatSelectionPage() {
  const { scheduleId } = useParams();
  const { state } = useLocation();
  const { user } = useAuth();
  const navigate = useNavigate();

  // If we came from ShowDetailPage with state, use it to skip extra API calls
  const passedSchedule = state?.schedule;
  const passedShow = state?.show;
  const passedVenues = state?.venues || [];

  const [schedule, setSchedule] = useState(passedSchedule || null);
  const [show, setShow] = useState(passedShow || null);
  const [seats, setSeats] = useState([]);
  const [selectedSeats, setSelectedSeats] = useState([]);
  const [lockedSeatIds, setLockedSeatIds] = useState([]); // locked by others
  const [myLocks, setMyLocks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [lockTimer, setLockTimer] = useState(null);
  const timerRef = useRef(null);
  const lockStartRef = useRef(null);

  const getVenueName = (venueId) => passedVenues.find(v => v.venueId === venueId)?.venueName || '';

  const fetchData = useCallback(async () => {
    try {
      // Get schedule if not passed
      let sc = schedule;
      if (!sc) {
        const r = await getScheduleById(scheduleId);
        sc = r.data;
        setSchedule(sc);
      }

      // Get seats by venue
      const venueId = sc.venueId;
      if (venueId) {
        const sr = await getSeatsByVenue(venueId);
        setSeats(sr.data || []);
      }

      // Get locks for this schedule
      const lr = await getLocksBySchedule(scheduleId);
      const locks = lr.data || [];
      // Seats locked by others (not current user)
      const othersLocked = locks
        .filter(l => l.status === 'LOCKED' && l.userId !== user?.userId)
        .map(l => l.seatId);
      setLockedSeatIds(othersLocked);
    } catch (err) {
      setError('Failed to load seat data.');
    }
    setLoading(false);
  }, [scheduleId, user, schedule]);

  useEffect(() => { fetchData(); }, []);

  // Countdown timer
  useEffect(() => {
    if (myLocks.length > 0 && !lockStartRef.current) {
      lockStartRef.current = Date.now();
      const end = Date.now() + LOCK_TIMEOUT_MINUTES * 60 * 1000;
      if (timerRef.current) clearInterval(timerRef.current);
      timerRef.current = setInterval(() => {
        const remaining = Math.max(0, Math.floor((end - Date.now()) / 1000));
        setLockTimer(remaining);
        if (remaining === 0) { clearInterval(timerRef.current); handleReleaseAll(); }
      }, 1000);
    }
    if (myLocks.length === 0) {
      if (timerRef.current) clearInterval(timerRef.current);
      setLockTimer(null);
      lockStartRef.current = null;
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [myLocks.length]);

  const handleSeatClick = async (seat) => {
    const alreadySelected = selectedSeats.find(s => s.seatId === seat.seatId);
    if (alreadySelected) {
      // Unlock
      const lockEntry = myLocks.find(l => l.seatId === seat.seatId);
      if (lockEntry) {
        try { await unlockSeat(lockEntry.lockId); } catch {}
        setMyLocks(prev => prev.filter(l => l.seatId !== seat.seatId));
      }
      setSelectedSeats(prev => prev.filter(s => s.seatId !== seat.seatId));
    } else {
      // Lock
      try {
        const res = await lockSeat({ seatId: seat.seatId, scheduleId: parseInt(scheduleId), userId: user.userId });
        const lockId = res.data?.lockId;
        setMyLocks(prev => [...prev, { lockId, seatId: seat.seatId }]);
        setSelectedSeats(prev => [...prev, seat]);
      } catch (err) {
        setError(err.response?.data?.message || 'Could not lock this seat — it may have just been taken.');
        setTimeout(() => setError(''), 3000);
        fetchData();
      }
    }
  };

  const handleReleaseAll = async () => {
    try { await Promise.allSettled(myLocks.map(l => unlockSeat(l.lockId))); } catch {}
    setMyLocks([]);
    setSelectedSeats([]);
    lockStartRef.current = null;
  };

  const handleProceed = () => {
    if (selectedSeats.length === 0) return;
    navigate('/portal/checkout', {
      state: {
        schedule,
        show,
        venueName: getVenueName(schedule?.venueId),
        selectedSeats,
        locks: myLocks,
        totalAmount: selectedSeats.reduce((s, seat) => s + (parseFloat(seat.price) || 0), 0),
      }
    });
  };

  const formatTimer = (s) => {
    if (s === null) return '';
    return `${Math.floor(s / 60).toString().padStart(2, '0')}:${(s % 60).toString().padStart(2, '0')}`;
  };

  const totalAmount = selectedSeats.reduce((s, seat) => s + (parseFloat(seat.price) || 0), 0);

  if (loading) return <div style={{ padding: 40 }}><div className="spinner" /></div>;

  return (
    <div style={{ maxWidth: 1100, margin: '0 auto', padding: '40px 24px' }} className="fade-in">
      <button className="btn btn-ghost" style={{ padding: '7px 14px', fontSize: 13, marginBottom: 16 }}
        onClick={() => { handleReleaseAll(); navigate(-1); }}>
        ← Back
      </button>

      {/* Schedule header */}
      {schedule && (
        <div className="card" style={{ padding: '16px 20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12, marginBottom: 24 }}>
          <div>
            <h2 style={{ fontSize: '1.2rem', marginBottom: 4 }}>{show?.title || `Schedule #${scheduleId}`}</h2>
            <div style={{ display: 'flex', gap: 16, color: 'var(--text-secondary)', fontSize: 13 }}>
              <span>📅 {schedule.showDate} at {schedule.showTime}</span>
              <span>📍 {getVenueName(schedule.venueId)}</span>
            </div>
          </div>
          {lockTimer !== null && (
            <div style={{
              background: lockTimer < 60 ? 'rgba(192,57,43,0.15)' : 'rgba(212,175,55,0.1)',
              border: `1px solid ${lockTimer < 60 ? 'rgba(192,57,43,0.4)' : 'var(--border-accent)'}`,
              borderRadius: 8, padding: '8px 16px', textAlign: 'center',
            }}>
              <div style={{ fontSize: 11, color: 'var(--text-muted)', letterSpacing: '1px', textTransform: 'uppercase', marginBottom: 2 }}>Seats held for</div>
              <div style={{ fontSize: 20, fontWeight: 700, fontFamily: 'monospace', color: lockTimer < 60 ? '#e74c3c' : 'var(--gold)' }}>
                {formatTimer(lockTimer)}
              </div>
            </div>
          )}
        </div>
      )}

      {error && <div className="alert alert-error" style={{ marginBottom: 16 }}>{error}</div>}

      <div className="seat-booking-layout">
        <div>
          <SeatLayout
            seats={seats}
            selectedSeats={selectedSeats}
            bookedSeatIds={[]}
            lockedSeatIds={lockedSeatIds}
            onSeatClick={handleSeatClick}
          />
        </div>

        <div className="booking-summary-panel">
          <h3>Booking Summary</h3>
          {selectedSeats.length === 0 ? (
            <div style={{ color: 'var(--text-muted)', fontSize: 14, textAlign: 'center', padding: '20px 0' }}>
              Click on seats to select them
            </div>
          ) : (
            <>
              <div style={{ marginBottom: 16 }}>
                <div style={{ fontSize: 11, fontWeight: 600, letterSpacing: '1px', textTransform: 'uppercase', color: 'var(--text-muted)', marginBottom: 8 }}>
                  Selected ({selectedSeats.length})
                </div>
                <div>
                  {selectedSeats.map(s => (
                    <span key={s.seatId} className="selected-seat-chip">
                      {s.seatNumber}
                      <span style={{ cursor: 'pointer', marginLeft: 2, opacity: 0.7 }} onClick={() => handleSeatClick(s)}>×</span>
                    </span>
                  ))}
                </div>
              </div>
              <div className="gold-line" />
              {selectedSeats.map(s => (
                <div key={s.seatId} className="price-row">
                  <span>{s.seatNumber} ({s.seatType})</span>
                  <span>₹{s.price || 0}</span>
                </div>
              ))}
              <div className="price-row total">
                <span>Total</span><span>₹{totalAmount}</span>
              </div>
            </>
          )}
          <button className="btn btn-primary proceed-btn" disabled={selectedSeats.length === 0} onClick={handleProceed}>
            Proceed to Checkout →
          </button>
          {selectedSeats.length > 0 && (
            <button className="btn btn-ghost" style={{ width: '100%', marginTop: 8, padding: '10px', fontSize: 13 }} onClick={handleReleaseAll}>
              Clear Selection
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
